namespace GenApp.Application.Persistence;

public interface IUnitOfWork
{
    Task SaveChangesAsync(CancellationToken cancellationToken = default);

    // ADR 0003 decision 2: needed when a write uses a key generated by an earlier SaveChanges
    // (customer_number → customer_secure). Disposing without CommitAsync rolls everything back.
    Task<ITransaction> BeginTransactionAsync(CancellationToken cancellationToken = default);
}

public interface ITransaction : IAsyncDisposable
{
    Task CommitAsync(CancellationToken cancellationToken = default);
}
